router.get("/", authenticateToken, async (req, res) => {
    try {
        if (req.user.role !== 'FM') return res.status(403).json({ message: "Unauthorized." });

        const users = await User.findAll({
            attributes: ['id', 'name', 'email', 'role', 'isActive', 'createdAt'],
