1	import React, { useState, useEffect } from 'react';
2	import axios from 'axios';
3	import Sidebar from '../components/Sidebar';
4	import '../css/Dashboard.css';
5	import '../css/Management.css';
6	import '../css/Booking.css';
7	
8	const BAYS = ['Bay A', 'Bay B'];
9	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
10	const STATUS_FLOW = { Pending: 'Confirmed', Confirmed: 'Arrived', Arrived: 'Completed' };
11	const CLOSED = ['Completed', 'Cancelled'];
12	
13	const emptyForm = {
14	  transport_company: '', license_plate: '', driver_phone: '',
15	  driver_name: '', loading_bay: '', slot_start: '', slot_end: '', notes: ''
16	};
17	
18	const TenantLogistics = () => {
19	  const [bookings, setBookings] = useState([]);
20	  const [loading, setLoading] = useState(true);
21	  const [error, setError] = useState('');
22	  const [notice, setNotice] = useState('');
23	  const [form, setForm] = useState(emptyForm);
24	  const [submitting, setSubmitting] = useState(false);
25	
26	  // Booking form is hidden by default and opens in a modal (keeps the list roomy).
27	  const [isFormOpen, setIsFormOpen] = useState(false);
28	  // Frontend-only filtering (backend has no booking filter endpoint).
29	  const [searchText, setSearchText] = useState('');
30	  const [filterStatus, setFilterStatus] = useState('All');
31	  const [filterBay, setFilterBay] = useState('All');
32	  const [filterDate, setFilterDate] = useState(''); // YYYY-MM-DD; empty = all dates
33	
34	  // Gate Scan (FM/Staff) — verify a driver pass by booking ref at the loading bay.
35	  const [gateOpen, setGateOpen] = useState(false);
36	  const [gateRef, setGateRef] = useState('');
37	  const [gatePlate, setGatePlate] = useState('');
38	  const [gateBusy, setGateBusy] = useState(false);
39	  const [gateError, setGateError] = useState('');
40	
41	  const token = localStorage.getItem('accessToken');
42	  const role = localStorage.getItem('userRole');
43	  const authHeader = { headers: { Authorization: `Bearer ${token}` } };
44	
45	  const canManage = role === 'FM';                                    // status updates (facility-level) — FM only
46	  const canGateScan = role === 'FM';                                  // gate entry/exit — FM only
47	  const canCreate = role === 'FM' || role === 'Tenant' || role === 'Staff'; // create bookings (Staff books for their unit)
48	
49	  const fetchBookings = async () => {
50	    setLoading(true);
51	    setError('');
52	    try {
53	      const res = await axios.get('/api/bookings/', authHeader);
54	      setBookings(Array.isArray(res.data) ? res.data : []);
55	    } catch (err) {
56	      console.error('Failed to fetch bookings:', err);
57	      setError('Could not load bookings. Please try again.');
58	      setBookings([]);
59	    } finally {
60	      setLoading(false);
61	    }
62	  };
63	
64	  useEffect(() => { fetchBookings(); }, []);
65	
66	  useEffect(() => {
67	    if (!notice) return;
68	    const t = setTimeout(() => setNotice(''), 5000);
69	    return () => clearTimeout(t);
70	  }, [notice]);
71	
72	  const onField = (e) => setForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
73	
74	  const openForm = () => { setError(''); setForm(emptyForm); setIsFormOpen(true); };
75	  const closeForm = () => setIsFormOpen(false);
76	
77	  const describeWhatsapp = (wa) => {
78	    if (!wa) return '';
79	    if (wa.simulated) return ' (WhatsApp simulated — disabled)';
80	    return wa.success ? ' (WhatsApp sent)' : ' (WhatsApp delivery pending)';
81	  };
82	
83	  const createBooking = async (e) => {
84	    e.preventDefault();
85	    setSubmitting(true);
86	    setError('');
87	    try {
88	      const res = await axios.post('/api/bookings/create', form, authHeader);
