107	      setError(err.response?.data?.error || 'Failed to update status.');
108	    }
109	  };
110	
111	  const cancelBooking = async (id) => {
112	    try {
113	      const res = await axios.patch(`/api/bookings/${id}/cancel`, {}, authHeader);
114	      setNotice(`Booking cancelled.${describeWhatsapp(res.data?.whatsapp)}`);
115	      fetchBookings();
116	    } catch (err) {
117	      setError(err.response?.data?.error || 'Failed to cancel booking.');
118	    }
119	  };
120	
121	  const openGate = () => { setGateError(''); setGateRef(''); setGatePlate(''); setGateOpen(true); };
122	  const closeGate = () => setGateOpen(false);
123	
124	  const gateScan = async (action) => {
125	    const ref = gateRef.trim();
126	    if (!ref) { setGateError('Enter a booking reference.'); return; }
127	    setGateBusy(true);
128	    setGateError('');
