170	    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
171	  };
172	
173	  // --- Frontend filtering ---
174	  const q = searchText.trim().toLowerCase();
175	  const filtered = bookings.filter((b) => {
176	    const matchesQ = !q || [b.booking_ref, b.license_plate, b.transport_company, b.driver_name]
177	      .some(v => String(v || '').toLowerCase().includes(q));
178	    const matchesStatus = filterStatus === 'All' || b.status === filterStatus;
179	    const matchesBay = filterBay === 'All' || b.loading_bay === filterBay;
180	    const matchesDate = !filterDate || slotDateKey(b) === filterDate;
181	    return matchesQ && matchesStatus && matchesBay && matchesDate;
182	  });
183	
184	  return (
185	    <div className="dashboard-layout">
186	      <Sidebar />
187	      <main className="dashboard-main">
188	        <header className="dashboard-header">
