195	            {canGateScan && (
196	              <button className="edit-btn" onClick={openGate}>Gate Scan</button>
197	            )}
198	            {canCreate && (
199	              <button className="new-booking-btn" onClick={openForm}>+ New Booking</button>
200	            )}
201	          </div>
202	        </header>
203	
204	        {notice && <div className="toast-notification">{notice}</div>}
205	        {error && !isFormOpen && <div className="error-banner" style={{ margin: '0 0 16px' }}>⚠️ {error}</div>}
206	
207	        {/* Summary cards */}
208	        <div className="logistics-stats">
209	          <div className="logistics-stat-card">
210	            <div className="stat-value">{stats.total}</div>
211	            <div className="stat-label">Today's Bookings</div>
212	          </div>
213	          <div className="logistics-stat-card">
214	            <div className="stat-value">{stats.pending}</div>
215	            <div className="stat-label">Pending</div>
216	          </div>
217	          <div className="logistics-stat-card">
218	            <div className="stat-value">{stats.bayA}</div>
219	            <div className="stat-label">Bay A Active</div>
