1	const express = require('express');
2	const router = express.Router();
3	const crypto = require('crypto');
4	const { Op } = require('sequelize');
5	const { Booking, User } = require('../models');
6	const { verifyToken, requireRole } = require('../middlewares/auth');
7	const whatsapp = require('../services/whatsappService');
8	
9	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
10	
11	function genRef() {
12	    return `FG-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
13	}
14	
15	// Resolve which tenant/unit a booking belongs to, based on who is creating it:
16	//   Tenant → their own id; Staff → their managerId (the tenant they work for); FM → optional body.tenantId.
17	// Returns null if it cannot be determined (FM with no tenantId, or Staff with no manager).
18	async function resolveTenantId(user, bodyTenantId) {
19	    if (user.role === 'Tenant') return user.id;
20	    if (user.role === 'Staff') {
21	        const staff = await User.findByPk(user.id, { attributes: ['managerId'] });
22	        return staff?.managerId ?? null;
23	    }
24	    return bodyTenantId || null; // FM
25	}
26	
27	// ---------------------------------------------------------------------------
28	// CREATE — FM, Tenant, or Staff create a loading-bay booking request. (400 on bad input)
29	// Staff may book on behalf of their tenant/unit (booking is linked to their managerId).
30	// ---------------------------------------------------------------------------
31	router.post('/create', verifyToken, requireRole('FM', 'Tenant', 'Staff'), async (req, res) => {
32	    try {
33	        const {
34	            transport_company, license_plate, driver_phone, loading_bay,
35	            driver_name, slot_start, slot_end, notes, tenant_name
36	        } = req.body;
37	
38	        const missing = ['transport_company', 'license_plate', 'driver_phone', 'loading_bay']
39	            .filter(f => !req.body[f] || !String(req.body[f]).trim());
40	        if (missing.length) {
41	            return res.status(400).json({ error: `Missing required field(s): ${missing.join(', ')}.` });
42	        }
43	        if (!/^[+\d][\d\s-]{6,}$/.test(String(driver_phone))) {
44	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
45	        }
46	
47	        // Optional slot-conflict guard (409) when a time window is supplied.
48	        if (slot_start && slot_end) {
49	            if (new Date(slot_end) <= new Date(slot_start)) {
50	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
51	            }
52	            const clash = await Booking.findOne({
53	                where: {
54	                    loading_bay,
55	                    status: { [Op.ne]: 'Cancelled' },
56	                    slot_start: { [Op.lt]: new Date(slot_end) },
57	                    slot_end: { [Op.gt]: new Date(slot_start) }
58	                }
59	            });
60	            if (clash) {
61	                return res.status(409).json({ error: `${loading_bay} is already booked for that time window.` });
62	            }
63	        }
64	
65	        // Link the booking to a tenant/unit so the right people can see it
66	        // (Tenant → self, Staff → their managerId, FM → optional body.tenantId).
67	        const tenantId = await resolveTenantId(req.user, req.body.tenantId);
68	
69	        const booking = await Booking.create({
70	            booking_ref: genRef(),
71	            transport_company,
72	            license_plate,
73	            driver_phone,
74	            loading_bay,
75	            driver_name: driver_name || null,
76	            slot_start: slot_start || null,
77	            slot_end: slot_end || null,
78	            notes: notes || null,
79	            tenant_name: tenant_name || null,
80	            tenantId,
81	            status: 'Pending'
82	        });
83	
84	        // Confirmation to the driver — non-fatal (must never fail the booking).
85	        let whatsappResult = null;
86	        try {
87	            whatsappResult = await whatsapp.sendBookingCreated(booking);
88	        } catch (waErr) {
89	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
90	        }
91	
92	        res.status(201).json({ message: 'Booking created.', booking, whatsapp: whatsappResult });
93	    } catch (err) {
94	        console.error('Booking create error:', err);
95	        res.status(500).json({ error: 'Internal server error while creating booking.' });
96	    }
97	});
98	
99	// ---------------------------------------------------------------------------
100	// READ (list) — FM sees all; Tenant sees own unit; Staff sees their unit's bookings.
101	// ---------------------------------------------------------------------------
102	router.get('/', verifyToken, async (req, res) => {
103	    try {
104	        const where = {};
105	        if (req.user.role === 'Tenant') {
106	            where.tenantId = req.user.id;
107	        } else if (req.user.role === 'Staff') {
108	            // Staff only see bookings for the tenant/unit they belong to.
109	            const tenantId = await resolveTenantId(req.user, null);
110	            where.tenantId = tenantId ?? -1; // -1 → matches nothing if no manager set
111	        }
112	        // FM → no filter (all bookings)
113	        const bookings = await Booking.findAll({ where, order: [['createdAt', 'DESC']], limit: 100 });
114	        res.status(200).json(bookings);
115	    } catch (err) {
116	        console.error('Booking list error:', err);
117	        res.status(500).json({ error: 'Could not retrieve bookings.' });
118	    }
119	});
120	
121	// READ (all) — FM-only compat alias (unscoped). Declared BEFORE '/:ref'.
122	router.get('/all', verifyToken, requireRole('FM'), async (req, res) => {
123	    try {
124	        const bookings = await Booking.findAll({ order: [['createdAt', 'DESC']], limit: 100 });
125	        res.status(200).json(bookings);
126	    } catch (err) {
127	        console.error('Booking list error:', err);
128	        res.status(500).json({ error: 'Could not retrieve bookings.' });
129	    }
130	});
131	
132	// ---------------------------------------------------------------------------
133	// UPDATE status — FM only (facility-level: Pending → Confirmed → Arrived → Completed).
134	// Confirmed → WhatsApp slot confirmation. Completed → auto next-in-line alert.
135	// ---------------------------------------------------------------------------
136	router.patch('/:id/status', verifyToken, requireRole('FM'), async (req, res) => {
137	    try {
138	        const { status } = req.body;
139	        if (!STATUSES.includes(status)) {
140	            return res.status(400).json({ error: `status must be one of: ${STATUSES.join(', ')}.` });
141	        }
142	
143	        const booking = await Booking.findByPk(req.params.id);
144	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
145	
146	        await booking.update({ status });
147	
148	        let whatsappResult = null;
149	        let nextInLine = null;
150	
151	        // All WhatsApp sends are non-fatal — a failure must never fail the status update.
152	        try {
153	            if (status === 'Confirmed') {
154	                whatsappResult = await whatsapp.sendBookingConfirmed(booking);
155	            } else if (status === 'Arrived') {
156	                whatsappResult = await whatsapp.sendBookingArrived(booking);
157	            } else if (status === 'Cancelled') {
158	                whatsappResult = await whatsapp.sendBookingCancelled(booking);
159	            } else if (status === 'Completed') {
160	                // Notify the leaving driver, then alert the next waiting booking for the same bay.
161	                whatsappResult = await whatsapp.sendBookingCompleted(booking);
162	                const next = await Booking.findOne({
163	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
164	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
165	                });
166	                if (next) {
167	                    await whatsapp.sendNextInLine(next);
168	                    nextInLine = next.booking_ref;
169	                }
170	            }
171	        } catch (waErr) {
172	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
173	        }
174	
175	        res.status(200).json({ message: `Booking ${status}.`, booking, whatsapp: whatsappResult, nextInLine });
176	    } catch (err) {
177	        console.error('Booking status error:', err);
178	        res.status(500).json({ error: 'Could not update booking status.' });
179	    }
180	});
181	
182	// ---------------------------------------------------------------------------
183	// CANCEL — FM, or the Tenant who owns it. Soft cancel (status='Cancelled').
184	// ---------------------------------------------------------------------------
185	router.patch('/:id/cancel', verifyToken, async (req, res) => {
186	    try {
187	        const booking = await Booking.findByPk(req.params.id);
188	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
189	
190	        const isFM = req.user.role === 'FM';
191	        const isOwnerTenant = req.user.role === 'Tenant' && booking.tenantId === req.user.id;
192	        if (!isFM && !isOwnerTenant) {
193	            return res.status(403).json({ error: 'You can only cancel your own bookings.' });
194	        }
195	
196	        await booking.update({ status: 'Cancelled' });
197	        const whatsappResult = await whatsapp.sendBookingCancelled(booking);
198	        res.status(200).json({ message: 'Booking cancelled.', booking, whatsapp: whatsappResult });
199	    } catch (err) {
200	        console.error('Booking cancel error:', err);
201	        res.status(500).json({ error: 'Could not cancel booking.' });
202	    }
203	});
204	
205	// ---------------------------------------------------------------------------
206	// GATE SCAN — FM only: scan/verify a driver pass by booking_ref at the bay.
207	//   body: { action: 'entry' | 'exit', observedPlate?: string }
208	//   entry: Pending/Confirmed → Arrived (+ WhatsApp arrival)
209	//   exit:  Arrived/Confirmed → Completed (+ WhatsApp completed + next-in-line)
210	// Plate mismatch is flagged (warn) but does not block. WhatsApp is non-fatal.
211	// ---------------------------------------------------------------------------
212	router.patch('/:ref/gate-scan', verifyToken, requireRole('FM'), async (req, res) => {
213	    try {
214	        const { action, observedPlate } = req.body;
215	        if (!['entry', 'exit'].includes(action)) {
216	            return res.status(400).json({ error: "action must be 'entry' or 'exit'." });
217	        }
218	
219	        const booking = await Booking.findOne({ where: { booking_ref: req.params.ref } });
220	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
221	
222	        // Optional plate verification (warn-only — never blocks the scan).
223	        let plateMatched = null;
224	        if (observedPlate && String(observedPlate).trim()) {
225	            const norm = (s) => String(s || '').toUpperCase().replace(/\s+/g, '');
226	            plateMatched = norm(observedPlate) === norm(booking.license_plate);
227	        }
228	
229	        let whatsappStatus = null;
230	        let nextInLine = null;
231	
232	        if (action === 'entry') {
233	            if (booking.status === 'Cancelled' || booking.status === 'Completed') {
234	                return res.status(409).json({ error: `Cannot mark arrival: booking is ${booking.status}.`, booking, plateMatched });
235	            }
236	            await booking.update({ status: 'Arrived', arrived_at: new Date() });
237	            try {
238	                whatsappStatus = await whatsapp.sendBookingArrived(booking);
239	            } catch (waErr) {
240	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
241	            }
242	        } else { // exit
243	            if (booking.status === 'Cancelled') {
244	                return res.status(409).json({ error: 'Cannot mark exit: booking is Cancelled.', booking, plateMatched });
245	            }
246	            if (booking.status === 'Completed') {
247	                // Idempotent — already completed, do not re-notify / re-trigger next-in-line.
248	                return res.status(200).json({
249	                    message: 'Booking already completed.', booking, action,
250	                    plateMatched, whatsappStatus: null, nextInLine: null, alreadyCompleted: true
251	                });
252	            }
253	            await booking.update({ status: 'Completed', completed_at: new Date() });
254	            try {
255	                whatsappStatus = await whatsapp.sendBookingCompleted(booking);
256	                const next = await Booking.findOne({
257	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
258	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
259	                });
260	                if (next) {
261	                    await whatsapp.sendNextInLine(next);
262	                    nextInLine = next.booking_ref;
263	                }
264	            } catch (waErr) {
265	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
266	            }
267	        }
268	
269	        return res.status(200).json({
270	            message: `Gate ${action} recorded.`, booking, action, plateMatched, whatsappStatus, nextInLine
271	        });
272	    } catch (err) {
273	        console.error('Gate scan error:', err);
274	        return res.status(500).json({ error: 'Could not process gate scan.' });
275	    }
276	});
277	
278	// ---------------------------------------------------------------------------
279	// PUBLIC — driver pass lookup by booking_ref. NO auth (driver has no login).
280	// MUST stay last so it doesn't shadow '/all' or '/'.
281	// ---------------------------------------------------------------------------
